if (!level.isClientSide()) {
    // code exécuté uniquement côté serveur
}
// Depuis 1.20.1 : level.isClientSide  (champ public, pas méthode)

@SubscribeEvent
public static void onPlayerTick(TickEvent.PlayerTickEvent event) {
    if (event.phase == TickEvent.Phase.END
            && !event.player.level().isClientSide()) {
        Player player = event.player;
        // appelé chaque tick côté serveur pour chaque joueur
    }
}

@SubscribeEvent
public static void onPlayerJoin(PlayerEvent.PlayerLoggedInEvent event) {
    Player player = event.getEntity();
    // joueur connecté
}

@SubscribeEvent
public static void onPlayerLeave(PlayerEvent.PlayerLoggedOutEvent event) { ... }

@SubscribeEvent
public static void onPlayerRespawn(PlayerEvent.PlayerRespawnEvent event) {
    Player player = event.getEntity();
    boolean endReturn = event.isEndConquered(); // retour depuis l'End ?
}

@SubscribeEvent
public static void onRightClickItem(PlayerInteractEvent.RightClickItem event) {
    Player player = event.getEntity();
    ItemStack stack = event.getItemStack();
    InteractionHand hand = event.getHand();
    // event.setCanceled(true) pour empêcher le use()
}

@SubscribeEvent
public static void onRightClickBlock(PlayerInteractEvent.RightClickBlock event) {
    BlockPos pos = event.getPos();
    Player player = event.getEntity();
    // event.setUseBlock(Event.Result.DENY)   → empêche l'interaction avec le bloc
    // event.setUseItem(Event.Result.DENY)    → empêche l'utilisation de l'item
}

@SubscribeEvent
public static void onHurt(LivingHurtEvent event) {
    float damage = event.getAmount();
    DamageSource source = event.getSource();
    LivingEntity victim = event.getEntity();

    event.setAmount(damage * 0.5f); // réduire les dégâts de 50 %
    // event.setCanceled(true);      // annuler complètement
}

@SubscribeEvent
public static void onDeath(LivingDeathEvent event) {
    LivingEntity victim = event.getEntity();
    DamageSource source  = event.getSource();
    if (source.getEntity() instanceof Player killer) {
        // un joueur a tué victim
    }
    // event.setCanceled(true); → empêcher la mort (remettre 1 PV)
}

@SubscribeEvent
public static void onAttack(LivingAttackEvent event) {
    // déclenché avant LivingHurtEvent — avant les réductions d'armure
    LivingEntity target = event.getEntity();
    float rawDamage = event.getAmount();
}

@SubscribeEvent
public static void onDrops(LivingDropsEvent event) {
    if (event.getEntity() instanceof Zombie) {
        Level level = event.getEntity().level();
        double x = event.getEntity().getX();
        double y = event.getEntity().getY();
        double z = event.getEntity().getZ();
        event.getDrops().add(
            new ItemEntity(level, x, y, z,
                new ItemStack(ModItems.RUBY.get())));
    }
}

@SubscribeEvent
public static void onBreak(BlockEvent.BreakEvent event) {
    BlockPos pos    = event.getPos();
    BlockState state = event.getState();
    Player player   = event.getPlayer();
    // event.setCanceled(true); → empêcher la casse
}

@SubscribeEvent
public static void onPlace(BlockEvent.EntityPlaceEvent event) {
    BlockPos pos        = event.getPos();
    BlockState placed   = event.getPlacedBlock();
    Entity entity       = event.getEntity(); // joueur ou piston
    // event.setCanceled(true); → empêcher la pose
}

@SubscribeEvent
public static void onJoinLevel(EntityJoinLevelEvent event) {
    if (event.getEntity() instanceof Zombie zombie) {
        // un zombie apparaît dans le monde
    }
    // event.setCanceled(true); → empêcher l'apparition
}

@SubscribeEvent
public static void onExplosion(ExplosionEvent.Detonate event) {
    List<BlockPos> affectedBlocks = event.getAffectedBlocks();
    affectedBlocks.removeIf(pos ->
        event.getLevel().getBlockState(pos).is(Blocks.OBSIDIAN));
}

@SubscribeEvent
public static void onItemCrafted(PlayerEvent.ItemCraftedEvent event) {
    ItemStack result = event.getCrafting();
    Player player = event.getEntity();
}

@SubscribeEvent
public static void onItemPickup(EntityItemPickupEvent event) {
    ItemEntity itemEntity = event.getItem();
    Player player = event.getEntity();
    // event.setCanceled(true); → empêcher le ramassage
}

@SubscribeEvent
public static void onLivingTick(LivingEvent.LivingTickEvent event) {
    if (event.getEntity() instanceof Zombie zombie
            && !zombie.level().isClientSide()) {
        // appelé chaque tick pour chaque entité LivingEntity
    }
}

@SubscribeEvent
public static void onItemFinish(LivingEntityUseItemEvent.Finish event) {
    LivingEntity user = event.getEntity();
    ItemStack stack   = event.getItem();
    // déclenché quand le chargement se termine (arc, crossbow, etc.)
}
